<?php $pageTitle='Customer Login'; require 'db/connection.php'; require 'includes/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $st=$pdo->prepare('SELECT * FROM users WHERE email=?');$st->execute([trim($_POST['email']??'')]);$user=$st->fetch(); if($user&&password_verify($_POST['password']??'',$user['password'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$user['id'],'name'=>$user['name'],'email'=>$user['email'],'phone'=>$user['phone']];redirect('index.php');}$error='Incorrect email or password.';} include 'includes/header.php'; ?><div class="form-page"><div class="panel"><span class="eyebrow">Your stay awaits</span><h1>Customer login</h1><?php show_flash(); ?><?php if(!empty($error)): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="button" type="submit">Log in</button></form><p class="muted">New here? <a href="register.php">Create an account</a></p><p class="muted">Admin? <a href="admin/login.php">Admin login</a></p></div></div><?php include 'includes/footer.php'; ?>
